    return json({ ok: true, session, marker: VIDEO_PLATFORM_MARKER });
  } catch (err) {
    return json({ error: err instanceof Error ? err.message : 'live status failed', marker: VIDEO_PLATFORM_MARKER }, 500);
  }
}

