    if (resp.status >= 200 && resp.status < 300) {
      setCachedEntry(key, body, resp.status);
      return { body, status: resp.status, expiresAt: Date.now() + FEED_CACHE_TTL_MS };
    }
    // On upstream error, cache empty results for 30s instead of propagating failure
    setCachedEntry(key, EMPTY_FEED_BODY, 200);
    return { body: EMPTY_FEED_BODY, status: 200, expiresAt: Date.now() + FEED_CACHE_TTL_MS };
  })();
